	if e.ReporterEmail != "" && (!strings.Contains(e.ReporterEmail, "@") || !strings.Contains(e.ReporterEmail, ".")) {
		return fmt.Errorf("domain: invalid reporterEmail address: %s", e.ReporterEmail)
	}
	return nil
}

