  1	// Package notification implements notification delivery and push transport.
  2	package notification
  3	
  4	import (
  5		"context"
  6		"errors"
  7		"fmt"
  8		"log"
  9		"time"
 10	
 11		"github.com/scottdensmore/petspotr/pkg/delivery"
 12		"github.com/scottdensmore/petspotr/pkg/domain"
 13		"github.com/scottdensmore/petspotr/pkg/pubsub"
 14		"github.com/scottdensmore/petspotr/pkg/store"
 15	)
 16	
 17	const defaultDeliveryLease = time.Minute
 18	
 19	// Worker subscribes to matchFound and lostPet events, dispatching multi-channel owner and community broadcast alerts.
 20	type Worker struct {
 21		broker        pubsub.Broker
 22		deliveryStore store.DeliveryOperationStore
 23		dispatcher    *MultiChannelDispatcher
 24		geoEngine     *GeoBroadcastEngine
 25		now           func() time.Time
 26		deliveryLease time.Duration
 27	}
 28	
 29	// NewWorker constructs a Worker instance with default multi-channel senders and geo broadcast engine.
 30	func NewWorker(br pubsub.Broker) *Worker {
 31		return NewWorkerWithStore(store.NewMemoryStore(), br)
 32	}
 33	
 34	// NewWorkerWithStore constructs a Worker with durable delivery operations.
 35	func NewWorkerWithStore(stateStore store.DeliveryOperationStore, br pubsub.Broker) *Worker {
 36		dispatcher := NewMultiChannelDispatcher(
 37			NewMockEmailSender(),
 38			NewMockSMSSender(),
 39			NewMockWebPushSender(),
 40		)
 41		return NewWorkerWithStoreAndDispatcher(stateStore, br, dispatcher)
 42	}
 43	
 44	// NewWorkerWithDispatcher constructs a Worker with a custom MultiChannelDispatcher.
 45	func NewWorkerWithDispatcher(br pubsub.Broker, dispatcher *MultiChannelDispatcher) *Worker {
 46		return NewWorkerWithStoreAndDispatcher(store.NewMemoryStore(), br, dispatcher)
 47	}
 48	
 49	// NewWorkerWithStoreAndDispatcher constructs a Worker with custom durable
 50	// state and provider dispatch dependencies.
 51	func NewWorkerWithStoreAndDispatcher(
 52		stateStore store.DeliveryOperationStore,
 53		br pubsub.Broker,
 54		dispatcher *MultiChannelDispatcher,
 55	) *Worker {
 56		geoEngine := NewGeoBroadcastEngine(DefaultSubscribers(), dispatcher)
 57		return &Worker{
 58			broker:        br,
 59			deliveryStore: stateStore,
 60			dispatcher:    dispatcher,
 61			geoEngine:     geoEngine,
 62			now:           time.Now,
 63			deliveryLease: defaultDeliveryLease,
 64		}
 65	}
 66	
 67	// Start registers subscriptions for matchFound and lostPet topics.
 68	func (w *Worker) Start(ctx context.Context) error {
 69		if err := ctx.Err(); err != nil {
 70			return err
 71		}
 72	
 73		if err := w.broker.Subscribe("matchFound", func(handlerCtx context.Context, data []byte) error {
 74			_, err := w.ProcessMatchFound(handlerCtx, data)
 75			return err
 76		}); err != nil {
 77			return err
 78		}
 79	
 80		return w.broker.Subscribe("lostPet", func(handlerCtx context.Context, data []byte) error {
 81			_, err := w.ProcessLostPetBroadcast(handlerCtx, data)
 82			return err
 83		})
 84	}
 85	
 86	// ProcessMatchFound converts a matchFound event payload into an OwnerNotification and dispatches multi-channel alerts.
 87	func (w *Worker) ProcessMatchFound(ctx context.Context, matchResultData []byte) (*domain.OwnerNotification, error) {
 88		if err := ctx.Err(); err != nil {
 89			return nil, err
 90		}
 91	
 92		var res domain.MatchResult
 93		envelope, err := domain.DecodeEventPayload(matchResultData, domain.EventTypeMatchFound, &res)
 94		if err != nil {
 95			return nil, fmt.Errorf("notification-service: failed to unmarshal MatchResult: %w", err)
 96		}
 97	
 98		if err := res.Validate(); err != nil {
 99			return nil, fmt.Errorf("notification-service: invalid MatchResult payload: %w", err)
100		}
101	
102		notif := &domain.OwnerNotification{
103			FromEmail:  "alerts@petspotr.io",
104			ToEmail:    "owner@example.com",
105			Subject:    fmt.Sprintf("Match Found for Your Pet (%s)", res.MatchedPetID),
106			PetName:    res.MatchedPetID,
107			MatchScore: res.Score,
108		}
109	
110		if err := notif.Validate(); err != nil {
111			return nil, fmt.Errorf("notification-service: notification validation failed: %w", err)
112		}
113	
114		notif.Body = notif.RenderEmailBody()
115	
116		log.Printf("[Notification Service] DISPATCHING NOTIFICATION to %s: %s (Score: %.2f)",
117			notif.ToEmail, notif.Subject, notif.MatchScore)
118	
119		if w.dispatcher == nil || w.deliveryStore == nil {
120			return nil, errors.New("notification-service: delivery dependencies are not configured")
121		}
122		envelopeID := ""
123		if envelope != nil {
124			envelopeID = envelope.ID
125		}
126		eventID, err := delivery.ResolveEventID(envelopeID, domain.EventTypeMatchFound, matchResultData)
127		if err != nil {
128			return nil, fmt.Errorf("notification-service: resolve matchFound identity: %w", err)
129		}
130		msg := &NotificationMessage{
131			RecipientID: res.MatchedPetID,
132			Email:       notif.ToEmail,
133			Phone:       "+12065550199",
134			PushToken:   "push-token-default",
135			Subject:     notif.Subject,
136			Body:        notif.Body,
137			Channels:    []Channel{ChannelEmail, ChannelSMS, ChannelPush},
138		}
139		results, err := w.dispatchNotification(ctx, eventID, msg)
140		if err != nil {
141			return nil, err
142		}
143		log.Printf("[Notification Service] Dispatched %d owner-notification channels successfully", len(results))
144	
145		return notif, nil
146	}
147	
148	func (w *Worker) dispatchNotification(
149		ctx context.Context,
150		eventID string,
151		message *NotificationMessage,
152	) ([]DispatchResult, error) {
153		channels := message.Channels
154		if len(channels) == 0 {
155			channels = []Channel{ChannelEmail}
156		}
157		allResults := make([]DispatchResult, 0, len(channels))
158		for _, channel := range channels {
159			now := w.now().UTC()
160			operation, err := delivery.NewOperation(eventID, message.RecipientID, string(channel), now)
161			if err != nil {
162				return allResults, fmt.Errorf("notification-service: create %s delivery operation: %w", channel, err)
163			}
164			claim, err := w.deliveryStore.ClaimDeliveryOperation(ctx, operation, now, w.deliveryLease)
165			if err != nil {
166				return allResults, fmt.Errorf("notification-service: claim %s delivery: %w", channel, err)
167			}
168			switch claim.State {
169			case delivery.ClaimCompleted:
170				allResults = append(allResults, DispatchResult{Channel: channel, Success: true})
171				continue
172			case delivery.ClaimInProgress:
173				return allResults, fmt.Errorf("notification-service: %s delivery: %w", channel, delivery.ErrOperationInProgress)
174			case delivery.ClaimAcquired:
175			default:
176				return allResults, fmt.Errorf("notification-service: unexpected %s delivery claim %q", channel, claim.State)
177			}
178	
179			channelMessage := *message
180			channelMessage.Channels = []Channel{channel}
181			channelMessage.IdempotencyKey = operation.IdempotencyKey
182			results, dispatchErr := w.dispatcher.Dispatch(ctx, &channelMessage)
183			if dispatchErr == nil {
184				if len(results) != 1 || results[0].Channel != channel || !results[0].Success {
185					if len(results) == 1 && results[0].Error != "" {
186						dispatchErr = errors.New(results[0].Error)
187					} else {
188						dispatchErr = fmt.Errorf("unexpected dispatch result %#v", results)
189					}
190				}
191			}
192			if dispatchErr != nil {
193				failureAt := w.now().UTC()
194				persistErr := w.deliveryStore.FailDeliveryOperation(
195					ctx,
196					operation.ID,
197					claim.Attempt,
198					failureAt,
199					dispatchErr.Error(),
200				)
201				return allResults, fmt.Errorf("notification-service: dispatch %s delivery: %w", channel, errors.Join(dispatchErr, persistErr))
202			}
203			if err := w.deliveryStore.CompleteDeliveryOperation(
204				ctx,
205				operation.ID,
206				claim.Attempt,
207				w.now().UTC(),
208			); err != nil {
209				return allResults, fmt.Errorf("notification-service: complete %s delivery: %w", channel, err)
210			}
211			allResults = append(allResults, results[0])
212		}
213		return allResults, nil
214	}
215	
216	// ProcessLostPetBroadcast processes a lostPet event payload and dispatches radius-based community broadcast alerts.
217	func (w *Worker) ProcessLostPetBroadcast(ctx context.Context, lostPetData []byte) ([]DispatchResult, error) {
218		if err := ctx.Err(); err != nil {
219			return nil, err
220		}
221	
222		evt, envelope, err := domain.DecodeLostPetReported(lostPetData)
223		if err != nil {
224			return nil, fmt.Errorf("notification-service: decode lost-pet report: %w", err)
225		}
226	
227		if w.geoEngine == nil {
228			return nil, fmt.Errorf("notification-service: geoEngine not configured")
229		}
230		if w.deliveryStore == nil {
231			return nil, fmt.Errorf("notification-service: delivery store not configured")
232		}
233		envelopeID := ""
234		if envelope != nil {
235			envelopeID = envelope.ID
236		}
237		eventID, err := delivery.ResolveEventID(envelopeID, domain.EventTypeLostPetReported, lostPetData)
238		if err != nil {
239			return nil, fmt.Errorf("notification-service: resolve lostPet identity: %w", err)
240		}
241	
242		return w.geoEngine.broadcastLostPetAlert(
243			ctx,
244			&evt,
245			5.0,
246			func(dispatchCtx context.Context, message *NotificationMessage) ([]DispatchResult, error) {
247				return w.dispatchNotification(dispatchCtx, eventID, message)
248			},
249		)
250	}

