 91	
 92		var res domain.MatchResult
 93		envelope, err := domain.DecodeEventPayload(matchResultData, domain.EventTypeMatchFound, &res)
 94		if err != nil {
 95			return nil, fmt.Errorf("notification-service: failed to unmarshal MatchResult: %w", err)
