 99			return nil, fmt.Errorf("notification-service: invalid MatchResult payload: %w", err)
100		}
101	
102		notif := &domain.OwnerNotification{
103			FromEmail:  "alerts@petspotr.io",
104			ToEmail:    "owner@example.com",
105			Subject:    fmt.Sprintf("Match Found for Your Pet (%s)", res.MatchedPetID),
106			PetName:    res.MatchedPetID,
107			MatchScore: res.Score,
108		}
109	
110		if err := notif.Validate(); err != nil {
111			return nil, fmt.Errorf("notification-service: notification validation failed: %w", err)
112		}
