148	func (w *Worker) dispatchNotification(
149		ctx context.Context,
150		eventID string,
151		message *NotificationMessage,
152	) ([]DispatchResult, error) {
153		channels := message.Channels
154		if len(channels) == 0 {
155			channels = []Channel{ChannelEmail}
156		}
157		allResults := make([]DispatchResult, 0, len(channels))
158		for _, channel := range channels {
159			now := w.now().UTC()
160			operation, err := delivery.NewOperation(eventID, message.RecipientID, string(channel), now)
161			if err != nil {
162				return allResults, fmt.Errorf("notification-service: create %s delivery operation: %w", channel, err)
163			}
164			claim, err := w.deliveryStore.ClaimDeliveryOperation(ctx, operation, now, w.deliveryLease)
165			if err != nil {
166				return allResults, fmt.Errorf("notification-service: claim %s delivery: %w", channel, err)
167			}
168			switch claim.State {
169			case delivery.ClaimCompleted:
170				allResults = append(allResults, DispatchResult{Channel: channel, Success: true})
171				continue
172			case delivery.ClaimInProgress:
173				return allResults, fmt.Errorf("notification-service: %s delivery: %w", channel, delivery.ErrOperationInProgress)
174			case delivery.ClaimAcquired:
175			default:
176				return allResults, fmt.Errorf("notification-service: unexpected %s delivery claim %q", channel, claim.State)
177			}
178	
179			channelMessage := *message
180			channelMessage.Channels = []Channel{channel}
181			channelMessage.IdempotencyKey = operation.IdempotencyKey
182			results, dispatchErr := w.dispatcher.Dispatch(ctx, &channelMessage)
183			if dispatchErr == nil {
184				if len(results) != 1 || results[0].Channel != channel || !results[0].Success {
185					if len(results) == 1 && results[0].Error != "" {
186						dispatchErr = errors.New(results[0].Error)
187					} else {
188						dispatchErr = fmt.Errorf("unexpected dispatch result %#v", results)
189					}
190				}
191			}
192			if dispatchErr != nil {
193				failureAt := w.now().UTC()
194				persistErr := w.deliveryStore.FailDeliveryOperation(
195					ctx,
196					operation.ID,
197					claim.Attempt,
198					failureAt,
199					dispatchErr.Error(),
200				)
201				return allResults, fmt.Errorf("notification-service: dispatch %s delivery: %w", channel, errors.Join(dispatchErr, persistErr))
202			}
203			if err := w.deliveryStore.CompleteDeliveryOperation(
204				ctx,
205				operation.ID,
206				claim.Attempt,
207				w.now().UTC(),
208			); err != nil {
209				return allResults, fmt.Errorf("notification-service: complete %s delivery: %w", channel, err)
210			}
211			allResults = append(allResults, results[0])
212		}
213		return allResults, nil
214	}
