 12	
 13	func TestNotificationWorker_ProcessMatchFound(t *testing.T) {
 14		ps := pubsub.NewMemoryPubSub()
 15		worker := NewWorker(ps)
 16	
 17		t.Run("valid matchFound event constructs and renders owner notification", func(t *testing.T) {
 18			matchRes := domain.MatchResult{
 19				FoundPetID:   "found-202",
 20				MatchedPetID: "lost-101",
 21				Score:        0.95,
 22				IsMatch:      true,
 23				Details:      "High visual match score",
 24			}
 25			data, _ := matchRes.ToJSON()
 26	
 27			notif, err := worker.ProcessMatchFound(context.Background(), data)
 28			if err != nil {
 29				t.Fatalf("ProcessMatchFound failed: %v", err)
 30			}
 31	
 32			if notif == nil {
 33				t.Fatal("expected non-nil OwnerNotification")
 34			}
 35	
 36			if notif.ToEmail == "" {
 37				t.Errorf("expected non-empty recipient email")
 38			}
 39	
 40			if notif.Body == "" {
 41				t.Errorf("expected rendered email body, got empty string")
 42			}
 43		})
 44	
 45		t.Run("invalid json event returns error", func(t *testing.T) {
 46			_, err := worker.ProcessMatchFound(context.Background(), []byte("{invalid-json"))
 47			if err == nil {
 48				t.Error("expected error for invalid json, got nil")
 49			}
 50		})
 51	
 52		t.Run("invalid domain payload returns error", func(t *testing.T) {
 53			invalidRes := domain.MatchResult{FoundPetID: ""}
 54			data, _ := invalidRes.ToJSON()
 55			_, err := worker.ProcessMatchFound(context.Background(), data)
 56			if err == nil {
 57				t.Error("expected error for invalid match result payload, got nil")
 58			}
 59		})
 60	
 61		t.Run("versioned matchFound envelope remains consumable", func(t *testing.T) {
 62			matchRes := domain.MatchResult{FoundPetID: "found-envelope", MatchedPetID: "lost-envelope", Score: 0.91, IsMatch: true}
 63			payload, _ := matchRes.ToJSON()
 64			envelope, err := domain.NewEventEnvelope(domain.EventEnvelopeInput{
 65				Type:             domain.EventTypeMatchFound,
 66				OccurredAt:       time.Now().UTC(),
 67				AggregateID:      "found-envelope:lost-envelope",
 68				AggregateVersion: 1,
 69				PayloadVersion:   1,
 70				Payload:          payload,
 71			})
 72			if err != nil {
 73				t.Fatal(err)
 74			}
 75			data, _ := json.Marshal(envelope)
 76			if _, err := worker.ProcessMatchFound(context.Background(), data); err != nil {
 77				t.Fatalf("ProcessMatchFound(envelope) error = %v", err)
 78			}
 79		})
 80	}
 81	
 82	func TestNotificationWorker_Start(t *testing.T) {
 83		ps := pubsub.NewMemoryPubSub()
 84		worker := NewWorker(ps)
 85	
 86		t.Run("Start registers matchFound subscription successfully", func(t *testing.T) {
 87			ctx := context.Background()
 88			if err := worker.Start(ctx); err != nil {
 89				t.Fatalf("worker.Start failed: %v", err)
 90			}
 91		})
 92	
 93		t.Run("Start returns error on cancelled context", func(t *testing.T) {
 94			ctx, cancel := context.WithCancel(context.Background())
 95			cancel()
 96			if err := worker.Start(ctx); err == nil {
 97				t.Error("expected error on cancelled context, got nil")
 98			}
 99		})
100	}

