111	// BeginImageUpload creates a V4 POST policy constrained to one generated key,
112	// one supported media type, exact metadata, a short expiry, and MaxImageBytes.
113	func (s *GCSImageStore) BeginImageUpload(ctx context.Context, intent ImageUploadIntent) (*ImageUploadGrant, error) {
114		if err := ctx.Err(); err != nil {
115			return nil, err
116		}
117		if intent.Purpose != ImagePurposeFoundPet {
118			return nil, fmt.Errorf("%w: unsupported purpose %q", ErrInvalidImage, intent.Purpose)
119		}
120		contentType, extension, ok := supportedImageType(intent.ContentType)
121		if !ok {
122			return nil, fmt.Errorf("%w: unsupported content type %q", ErrInvalidImage, intent.ContentType)
123		}
124		token, err := randomHex(16)
125		if err != nil {
126			return nil, err
127		}
128		reportID := "found-" + token
129		finalizeToken, err := randomHex(32)
130		if err != nil {
131			return nil, err
132		}
133		objectName := fmt.Sprintf("uploads/found-pets/%s/image%s", reportID, extension)
134		expiresAt := s.now().UTC().Add(uploadExpiry)
135		policy, err := s.backend.GenerateSignedPostPolicyV4(objectName, &storage.PostPolicyV4Options{
136			Expires: expiresAt,
137			Fields: &storage.PolicyV4Fields{
138				ContentType:         contentType,
139				StatusCodeOnSuccess: http.StatusCreated,
140				Metadata: map[string]string{
141					metadataReportIDField:    reportID,
142					metadataPurposeField:     string(ImagePurposeFoundPet),
143					metadataUploadTokenField: tokenDigest(finalizeToken),
144					metadataFinalizeField:    strconv.FormatInt(expiresAt.Unix(), 10),
145				},
146			},
147			Conditions: []storage.PostPolicyV4Condition{
148				storage.ConditionContentLengthRange(1, uint64(MaxImageBytes)),
149			},
150		})
151		if err != nil {
152			return nil, fmt.Errorf("blob: sign GCS upload policy: %w", err)
153		}
154		return &ImageUploadGrant{
155			UploadURL:     policy.URL,
156			FormFields:    policy.Fields,
157			ReportID:      reportID,
158			FinalizeToken: finalizeToken,
159			ObjectName:    objectName,
160			ContentType:   contentType,
161			MaxBytes:      MaxImageBytes,
162			ExpiresAt:     expiresAt,
163		}, nil
164	}
