302	// CleanupOrphanedFinalizedImages deletes only old, valid finalized objects
303	// that remain unreferenced across two durable-state checks. Listing is
304	// cursor-backed and bounded; deletion is pinned to the inspected generation.
305	func (s *GCSImageStore) CleanupOrphanedFinalizedImages(
306		ctx context.Context,
307		createdBefore time.Time,
308		limit int,
309		referenced FinalizedImageReferenceChecker,
310	) (int, error) {
311		if referenced == nil {
312			return 0, errors.New("blob: finalized image reference checker is required")
313		}
314		if limit <= 0 || limit > MaxOrphanCleanupBatch {
315			limit = MaxOrphanCleanupBatch
316		}
317		s.cleanupMu.Lock()
318		defer s.cleanupMu.Unlock()
319	
320		objects, nextCursor, err := s.backend.List(ctx, "images/found-pets/", s.cleanupCursor, limit)
321		if err != nil {
322			return 0, fmt.Errorf("blob: list finalized GCS images: %w", err)
323		}
324		s.cleanupCursor = nextCursor
325		deleted := 0
326		for _, candidate := range objects {
327			if candidate.Created.IsZero() || !candidate.Created.Before(createdBefore) {
328				continue
329			}
330			reportID := finalizedReportID(candidate.Name)
331			if _, err := finalizedFromAttrs(reportID, candidate); err != nil {
332				continue
333			}
334			isReferenced, err := referenced(ctx, reportID, candidate.Name)
335			if err != nil {
336				return deleted, fmt.Errorf("blob: check finalized image reference: %w", err)
337			}
338			if isReferenced {
339				continue
340			}
341			current, err := s.backend.Attrs(ctx, candidate.Name)
342			if errors.Is(err, ErrNotFound) {
343				continue
344			}
345			if err != nil {
346				return deleted, fmt.Errorf("blob: recheck finalized GCS image generation: %w", err)
347			}
348			if current.Generation != candidate.Generation {
349				continue
350			}
351			isReferenced, err = referenced(ctx, reportID, candidate.Name)
352			if err != nil {
353				return deleted, fmt.Errorf("blob: recheck finalized image reference: %w", err)
354			}
355			if isReferenced {
356				continue
357			}
358			if err := s.backend.Delete(ctx, candidate.Name, candidate.Generation); err != nil {
359				return deleted, fmt.Errorf("blob: delete orphaned finalized GCS image: %w", err)
360			}
361			deleted++
362		}
363		return deleted, nil
364	}
