200		ctx := context.Background()
201		backend := newFakeGCSBackend()
202		images := newGCSImageStore(backend)
203		old := time.Now().UTC().Add(-DefaultOrphanGracePeriod - time.Hour)
204		addFinalObject := func(reportID string, generation int64) string {
205			name := "images/found-pets/" + reportID + "/image.jpg"
206			backend.objects[name] = fakeGCSObject{attrs: gcsObjectAttrs{
207				Name: name, ContentType: "image/jpeg", Size: 100, Generation: generation, Created: old,
208				Metadata: map[string]string{
209					metadataReportID: reportID, metadataPurpose: string(ImagePurposeFoundPet),
210					metadataWidth: "2", metadataHeight: "3", metadataUploadToken: strings.Repeat("a", 64),
211					metadataFinalizeBefore: strconv.FormatInt(old.Unix(), 10),
212				},
213			}}
214			return name
215		}
216		orphan := addFinalObject("found-orphan", 10)
217		referenced := addFinalObject("found-referenced", 11)
218		concurrent := addFinalObject("found-concurrent", 12)
219		replaced := addFinalObject("found-replaced", 13)
220		checks := make(map[string]int)
221		backend.beforeAttrs = func(object string) {
222			if object == replaced {
223				value := backend.objects[object]
224				value.attrs.Generation = 14
225				backend.objects[object] = value
226				backend.beforeAttrs = nil
227			}
228		}
229	
230		deleted, err := images.CleanupOrphanedFinalizedImages(
231			ctx,
232			time.Now().UTC().Add(-DefaultOrphanGracePeriod),
233			MaxOrphanCleanupBatch,
234			func(_ context.Context, _ string, objectName string) (bool, error) {
235				checks[objectName]++
236				switch objectName {
237				case referenced:
238					return true, nil
239				case concurrent:
240					return checks[objectName] == 2, nil
241				default:
242					return false, nil
243				}
244			},
245		)
246		if err != nil {
247			t.Fatalf("CleanupOrphanedFinalizedImages() error = %v", err)
248		}
249		if deleted != 1 {
250			t.Fatalf("deleted = %d, want 1", deleted)
251		}
252		if _, ok := backend.objects[orphan]; ok {
253			t.Fatal("unreferenced finalized object was preserved")
254		}
255		for _, preserved := range []string{referenced, concurrent, replaced} {
256			if _, ok := backend.objects[preserved]; !ok {
257				t.Fatalf("safe object %q was deleted", preserved)
258			}
259		}
260	}
