290	func assertPostPolicyConstraints(t *testing.T, encodedPolicy, objectName, reportID, tokenHash, deadline string) {
291		t.Helper()
292		policyJSON, err := base64.StdEncoding.DecodeString(encodedPolicy)
293		if err != nil {
