166	// FinalizeImage verifies immutable object attributes and decoded bytes before
167	// copying the object into the private finalized namespace.
168	func (s *GCSImageStore) FinalizeImage(ctx context.Context, reportID, objectName, finalizeToken string) (*FinalizedImage, error) {
169		contentType, finalName, err := validateUploadBinding(reportID, objectName)
170		if err != nil {
171			return nil, err
172		}
173	
174		if attrs, attrsErr := s.backend.Attrs(ctx, finalName); attrsErr == nil {
175			if !tokenMatches(attrs.Metadata[metadataUploadToken], finalizeToken) {
176				return nil, ErrUploadMismatch
177			}
178			if err := s.validateFinalizeDeadline(attrs.Metadata); err != nil {
179				return nil, err
180			}
181			return finalizedFromAttrs(reportID, attrs)
182		} else if !errors.Is(attrsErr, ErrNotFound) {
183			return nil, fmt.Errorf("blob: inspect finalized GCS image: %w", attrsErr)
184		}
185	
186		attrs, err := s.backend.Attrs(ctx, objectName)
187		if err != nil {
188			return nil, fmt.Errorf("blob: inspect uploaded GCS image: %w", err)
189		}
190		if attrs.Name != objectName || attrs.ContentType != contentType ||
191			attrs.Metadata[metadataReportID] != reportID ||
192			attrs.Metadata[metadataPurpose] != string(ImagePurposeFoundPet) {
193			return nil, ErrUploadMismatch
194		}
195		if !tokenMatches(attrs.Metadata[metadataUploadToken], finalizeToken) {
196			return nil, ErrUploadMismatch
197		}
198		if err := s.validateFinalizeDeadline(attrs.Metadata); err != nil {
199			return nil, err
200		}
201		if attrs.Size <= 0 || attrs.Size > MaxImageBytes {
202			return nil, fmt.Errorf("%w: object size %d", ErrInvalidImage, attrs.Size)
203		}
204		data, err := s.backend.Read(ctx, objectName, attrs.Generation, MaxImageBytes+1)
205		if err != nil {
206			return nil, fmt.Errorf("blob: read uploaded GCS image: %w", err)
207		}
208		if int64(len(data)) != attrs.Size {
209			return nil, fmt.Errorf("%w: object size changed during validation", ErrInvalidImage)
210		}
211		width, height, err := validateImage(data, contentType)
212		if err != nil {
213			return nil, err
214		}
215		finalAttrs, err := s.backend.Copy(ctx, finalName, objectName, attrs.Generation, gcsObjectAttrs{
216			ContentType: contentType,
217			Size:        attrs.Size,
218			Metadata: map[string]string{
219				metadataReportID:       reportID,
220				metadataPurpose:        string(ImagePurposeFoundPet),
221				metadataWidth:          strconv.Itoa(width),
222				metadataHeight:         strconv.Itoa(height),
223				metadataUploadToken:    attrs.Metadata[metadataUploadToken],
224				metadataFinalizeBefore: attrs.Metadata[metadataFinalizeBefore],
225			},
226		})
227		if err != nil {
228			if isPreconditionFailed(err) {
229				if existing, attrsErr := s.backend.Attrs(ctx, finalName); attrsErr == nil {
230					if !tokenMatches(existing.Metadata[metadataUploadToken], finalizeToken) {
231						return nil, ErrUploadMismatch
232					}
233					if err := s.validateFinalizeDeadline(existing.Metadata); err != nil {
234						return nil, err
235					}
236					return finalizedFromAttrs(reportID, existing)
237				}
238			}
239			return nil, fmt.Errorf("blob: finalize GCS image: %w", err)
240		}
241		if err := s.backend.Delete(ctx, objectName, attrs.Generation); err != nil {
242			return nil, fmt.Errorf("blob: delete temporary GCS image: %w", err)
243		}
244		return finalizedFromAttrs(reportID, finalAttrs)
245	}
