247	// GenerateImageReadURL creates a private, short-lived V4 GET capability.
248	func (s *GCSImageStore) GenerateImageReadURL(ctx context.Context, objectName string, expiry time.Duration) (string, error) {
249		if err := ctx.Err(); err != nil {
250			return "", err
251		}
252		attrs, err := s.backend.Attrs(ctx, objectName)
253		if err != nil {
254			if errors.Is(err, ErrNotFound) {
255				return "", ErrNotFinalized
256			}
257			return "", fmt.Errorf("blob: inspect private GCS image: %w", err)
258		}
259		if _, err := finalizedFromAttrs(finalizedReportID(objectName), attrs); err != nil {
260			return "", ErrNotFinalized
261		}
262		if expiry <= 0 || expiry > maxReadExpiry {
263			expiry = maxReadExpiry
264		}
265		readURL, err := s.backend.SignedURL(objectName, &storage.SignedURLOptions{
266			Method:          http.MethodGet,
267			Expires:         s.now().UTC().Add(expiry),
268			Scheme:          storage.SigningSchemeV4,
269			QueryParameters: nil,
270		})
271		if err != nil {
272			return "", fmt.Errorf("blob: sign private GCS read URL: %w", err)
273		}
274		return readURL, nil
275	}
