369	func (s *GCSImageStore) validateFinalizeDeadline(metadata map[string]string) error {
370		deadlineUnix, err := strconv.ParseInt(metadata[metadataFinalizeBefore], 10, 64)
371		if err != nil || deadlineUnix <= 0 {
372			return ErrUploadMismatch
373		}
374		if !s.now().UTC().Before(time.Unix(deadlineUnix, 0).UTC()) {
375			return ErrUploadExpired
376		}
377		return nil
378	}
