380	func validateUploadBinding(reportID, objectName string) (string, string, error) {
381		if strings.TrimSpace(reportID) == "" || strings.Contains(reportID, "/") {
382			return "", "", ErrUploadMismatch
383		}
384		prefix := "uploads/found-pets/" + reportID + "/image"
385		if !strings.HasPrefix(objectName, prefix) {
386			return "", "", ErrUploadMismatch
387		}
388		extension := strings.TrimPrefix(objectName, prefix)
389		var contentType string
390		switch extension {
391		case ".jpg":
392			contentType = "image/jpeg"
393		case ".png":
394			contentType = "image/png"
395		default:
396			return "", "", ErrUploadMismatch
397		}
398		return contentType, "images/found-pets/" + reportID + "/image" + extension, nil
399	}
