401	func finalizedFromAttrs(reportID string, attrs gcsObjectAttrs) (*FinalizedImage, error) {
402		wantJPEG := "images/found-pets/" + reportID + "/image.jpg"
403		wantPNG := "images/found-pets/" + reportID + "/image.png"
404		validNameAndType := attrs.Name == wantJPEG && attrs.ContentType == "image/jpeg" ||
405			attrs.Name == wantPNG && attrs.ContentType == "image/png"
406		if reportID == "" || !validNameAndType || attrs.Size <= 0 || attrs.Size > MaxImageBytes ||
407			attrs.Metadata[metadataReportID] != reportID ||
408			attrs.Metadata[metadataPurpose] != string(ImagePurposeFoundPet) ||
409			len(attrs.Metadata[metadataUploadToken]) != sha256.Size*2 {
410			return nil, ErrNotFinalized
411		}
412		deadlineUnix, deadlineErr := strconv.ParseInt(attrs.Metadata[metadataFinalizeBefore], 10, 64)
413		if deadlineErr != nil || deadlineUnix <= 0 {
414			return nil, ErrNotFinalized
415		}
416		width, widthErr := strconv.Atoi(attrs.Metadata[metadataWidth])
417		height, heightErr := strconv.Atoi(attrs.Metadata[metadataHeight])
418		if widthErr != nil || heightErr != nil || width <= 0 || height <= 0 {
419			return nil, ErrNotFinalized
420		}
421		return &FinalizedImage{
422			ObjectName: attrs.Name, ContentType: attrs.ContentType, Size: attrs.Size,
423			Width: width, Height: height, Generation: attrs.Generation,
424		}, nil
425	}
