290	func assertPostPolicyConstraints(t *testing.T, encodedPolicy, objectName, reportID, tokenHash, deadline string) {
291		t.Helper()
292		policyJSON, err := base64.StdEncoding.DecodeString(encodedPolicy)
293		if err != nil {
294			t.Fatalf("decode post policy: %v", err)
295		}
296		var policy struct {
297			Conditions []any `json:"conditions"`
298		}
299		if err := json.Unmarshal(policyJSON, &policy); err != nil {
300			t.Fatalf("unmarshal post policy: %v", err)
301		}
302		serialized := string(policyJSON)
303		for _, required := range []string{
304			`["content-length-range",1,10485760]`,
305			`"content-type":"image/jpeg"`,
306			`"key":"` + objectName + `"`,
307			`"x-goog-meta-petspotr-report-id":"` + reportID + `"`,
308			`"x-goog-meta-petspotr-purpose":"found-pet"`,
309			`"x-goog-meta-petspotr-upload-token-sha256":"` + tokenHash + `"`,
310			`"x-goog-meta-petspotr-finalize-before":"` + deadline + `"`,
311		} {
312			if !strings.Contains(serialized, required) {
313				t.Fatalf("post policy %s does not contain %s", serialized, required)
314			}
315		}
316	}
