   277	// ReadFinalizedImage reads a validated private object for an internal service.
   278	func (s *GCSImageStore) ReadFinalizedImage(ctx context.Context, objectName string) ([]byte, error) {
   279		attrs, err := s.backend.Attrs(ctx, objectName)
   280		if err != nil {
   281			if errors.Is(err, ErrNotFound) {
   282				return nil, ErrNotFinalized
   283			}
   284			return nil, fmt.Errorf("blob: inspect private GCS image: %w", err)
   285		}
   286		if _, err := finalizedFromAttrs(finalizedReportID(objectName), attrs); err != nil {
   287			return nil, ErrNotFinalized
   288		}
   289		if attrs.Size <= 0 || attrs.Size > MaxImageBytes {
   290			return nil, fmt.Errorf("%w: object size %d", ErrInvalidImage, attrs.Size)
   291		}
   292		data, err := s.backend.Read(ctx, objectName, attrs.Generation, MaxImageBytes+1)
   293		if err != nil {
   294			return nil, fmt.Errorf("blob: read private GCS image: %w", err)
   295		}
   296		if int64(len(data)) != attrs.Size {
   297			return nil, fmt.Errorf("%w: object size changed during read", ErrInvalidImage)
   298		}
   299		return data, nil
   300	}
