   318	func encodedGCSImage(t *testing.T, format string) []byte {
   319		t.Helper()
   320		img := image.NewRGBA(image.Rect(0, 0, 2, 3))
   321		img.Set(0, 0, color.RGBA{R: 255, A: 255})
   322		var output bytes.Buffer
   323		var err error
   324		switch format {
   325		case "jpeg":
   326			err = jpeg.Encode(&output, img, nil)
   327		case "png":
   328			err = png.Encode(&output, img)
   329		default:
   330			t.Fatalf("unsupported test format %q", format)
   331		}
   332		if err != nil {
   333			t.Fatalf("encode %s: %v", format, err)
   334		}
   335		return output.Bytes()
   336	}
