   198		if err := s.validateFinalizeDeadline(attrs.Metadata); err != nil {
   199			return nil, err
   200		}
   201		if attrs.Size <= 0 || attrs.Size > MaxImageBytes {
   202			return nil, fmt.Errorf("%w: object size %d", ErrInvalidImage, attrs.Size)
