 24	func TestGCSImageStoreSecureLifecycle(t *testing.T) {
 25		ctx := context.Background()
 26		backend := newFakeGCSBackend()
 27		images := newGCSImageStore(backend)
 28	
 29		grant, err := images.BeginImageUpload(ctx, ImageUploadIntent{
 30			Purpose:     ImagePurposeFoundPet,
 31			FileName:    "../../caller-controlled.jpg",
 32			ContentType: "image/jpeg",
 33		})
 34		if err != nil {
 35			t.Fatalf("BeginImageUpload() error = %v", err)
 36		}
 37		if !strings.HasPrefix(grant.ObjectName, "uploads/found-pets/"+grant.ReportID+"/") ||
 38			strings.Contains(grant.ObjectName, "caller-controlled") {
 39			t.Fatalf("generated object name trusted caller input: %q", grant.ObjectName)
 40		}
 41		if grant.FormFields["key"] != grant.ObjectName ||
 42			grant.FormFields[metadataReportIDField] != grant.ReportID ||
 43			grant.FormFields[metadataPurposeField] != string(ImagePurposeFoundPet) ||
 44			grant.FormFields[metadataUploadTokenField] != tokenDigest(grant.FinalizeToken) ||
 45			grant.FormFields[metadataFinalizeField] != strconv.FormatInt(grant.ExpiresAt.Unix(), 10) {
 46			t.Fatalf("upload form fields do not bind the generated report: %#v", grant.FormFields)
 47		}
 48		assertPostPolicyConstraints(
 49			t,
 50			grant.FormFields["policy"],
 51			grant.ObjectName,
 52			grant.ReportID,
 53			tokenDigest(grant.FinalizeToken),
 54			strconv.FormatInt(grant.ExpiresAt.Unix(), 10),
 55		)
 56	
 57		imageBytes := encodedGCSImage(t, "jpeg")
 58		backend.objects[grant.ObjectName] = fakeGCSObject{
 59			attrs: gcsObjectAttrs{
 60				Name:        grant.ObjectName,
 61				ContentType: "image/jpeg",
 62				Size:        int64(len(imageBytes)),
 63				Generation:  7,
 64				Metadata: map[string]string{
 65					metadataReportID:       grant.ReportID,
 66					metadataPurpose:        string(ImagePurposeFoundPet),
 67					metadataUploadToken:    tokenDigest(grant.FinalizeToken),
 68					metadataFinalizeBefore: strconv.FormatInt(grant.ExpiresAt.Unix(), 10),
 69				},
 70			},
 71			data: imageBytes,
 72		}
 73	
 74		finalized, err := images.FinalizeImage(ctx, grant.ReportID, grant.ObjectName, grant.FinalizeToken)
 75		if err != nil {
 76			t.Fatalf("FinalizeImage() error = %v", err)
 77		}
 78		wantFinal := "images/found-pets/" + grant.ReportID + "/image.jpg"
 79		if finalized.ObjectName != wantFinal || finalized.Width != 2 || finalized.Height != 3 {
 80			t.Fatalf("FinalizeImage() = %#v, want %q and decoded dimensions", finalized, wantFinal)
 81		}
 82		if _, ok := backend.objects[grant.ObjectName]; ok {
 83			t.Fatal("temporary object was not deleted")
 84		}
 85		if backend.copySourceGeneration != 7 {
 86			t.Fatalf("copy source generation = %d, want 7", backend.copySourceGeneration)
 87		}
 88	
 89		readURL, err := images.GenerateImageReadURL(ctx, finalized.ObjectName, 5*time.Minute)
 90		if err != nil {
 91			t.Fatalf("GenerateImageReadURL() error = %v", err)
 92		}
 93		if !strings.Contains(readURL, "X-Goog-Signature=") || backend.readMethod != http.MethodGet {
 94			t.Fatalf("private read URL = %q, method = %q", readURL, backend.readMethod)
 95		}
 96		if backend.readExpires.After(time.Now().UTC().Add(6 * time.Minute)) {
 97			t.Fatalf("read expiry = %v, want short-lived URL", backend.readExpires)
 98		}
 99	
100		again, err := images.FinalizeImage(ctx, grant.ReportID, grant.ObjectName, grant.FinalizeToken)
101		if err != nil || again.ObjectName != finalized.ObjectName {
102			t.Fatalf("idempotent FinalizeImage() = %#v, %v", again, err)
103		}
104	}
