 36		})
 37		if err != nil {
 38			t.Fatalf("BeginImageUpload() error = %v", err)
 39		}
 40		_, finalName, err := validateUploadBinding(grant.ReportID, grant.ObjectName)
 41		if err != nil {
 42			t.Fatalf("validate generated upload binding: %v", err)
 43		}
 44		registerGCSIntegrationCleanup(t, images, grant.ObjectName, finalName)
 45		imageBytes := encodedGCSImage(t, "png")
 46		if err := uploadSignedPost(ctx, grant, imageBytes); err != nil {
 47			t.Fatalf("signed POST upload: %v", err)
 48		}
 49		finalized, err := images.FinalizeImage(ctx, grant.ReportID, grant.ObjectName, grant.FinalizeToken)
 50		if err != nil {
 51			t.Fatalf("FinalizeImage() error = %v", err)
 52		}
 53		readBytes, err := images.ReadFinalizedImage(ctx, finalized.ObjectName)
 54		if err != nil {
 55			t.Fatalf("ReadFinalizedImage() error = %v", err)
 56		}
 57		if !bytes.Equal(readBytes, imageBytes) {
 58			t.Fatal("finalized image bytes differ from uploaded bytes")
 59		}
 60		readURL, err := images.GenerateImageReadURL(ctx, finalized.ObjectName, time.Minute)
 61		if err != nil {
 62			t.Fatalf("GenerateImageReadURL() error = %v", err)
 63		}
 64		request, err := http.NewRequestWithContext(ctx, http.MethodGet, readURL, nil)
 65		if err != nil {
 66			t.Fatal(err)
 67		}
 68		response, err := http.DefaultClient.Do(request)
 69		if err != nil {
 70			t.Fatalf("GET signed read URL: %v", err)
 71		}
 72		defer func() { _ = response.Body.Close() }()
 73		if response.StatusCode != http.StatusOK {
 74			body, _ := io.ReadAll(io.LimitReader(response.Body, 4096))
 75			t.Fatalf("GET signed read URL status = %d: %s", response.StatusCode, body)
 76		}
 77	}
