 79	func registerGCSIntegrationCleanup(t *testing.T, images *GCSImageStore, objectNames ...string) {
 80		t.Helper()
 80		t.Helper()
 81		t.Cleanup(func() {
 82			cleanupCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 83			defer cancel()
 84			for _, objectName := range objectNames {
 85				attrs, err := images.backend.Attrs(cleanupCtx, objectName)
 86				if errors.Is(err, ErrNotFound) {
 87					continue
 88				}
 89				if err != nil {
 90					t.Errorf("inspect GCS integration object %q during cleanup: %v", objectName, err)
 91					continue
 92				}
 93				if err := images.backend.Delete(cleanupCtx, objectName, attrs.Generation); err != nil {
 94					t.Errorf("delete GCS integration object %q generation %d: %v", objectName, attrs.Generation, err)
 95				}
 96			}
 97		})
 98	}
 99	
100	func uploadSignedPost(ctx context.Context, grant *ImageUploadGrant, data []byte) error {
101		var body bytes.Buffer
102		writer := multipart.NewWriter(&body)
103		for name, value := range grant.FormFields {
104			if err := writer.WriteField(name, value); err != nil {
105				return err
106			}
107		}
108		header := make(textproto.MIMEHeader)
109		header.Set("Content-Disposition", `form-data; name="file"; filename="pet.png"`)
110		header.Set("Content-Type", grant.ContentType)
111		file, err := writer.CreatePart(header)
112		if err != nil {
113			return err
114		}
115		if _, err := file.Write(data); err != nil {
116			return err
117		}
118		if err := writer.Close(); err != nil {
119			return err
120		}
121		request, err := http.NewRequestWithContext(ctx, http.MethodPost, grant.UploadURL, &body)
122		if err != nil {
123			return err
124		}
125		request.Header.Set("Content-Type", writer.FormDataContentType())
126		response, err := http.DefaultClient.Do(request)
127		if err != nil {
128			return err
129		}
130		defer func() { _ = response.Body.Close() }()
131		if response.StatusCode != http.StatusCreated {
132			responseBody, _ := io.ReadAll(io.LimitReader(response.Body, 4096))
133			return fmt.Errorf("status %d: %s", response.StatusCode, responseBody)
134		}
135		return nil
136	}

