     1	// Package petmatcher implements the found-pet matching application worker.
     2	package petmatcher
     3	
     4	import (
     5		"context"
     6		"encoding/base64"
     7		"encoding/json"
     8		"errors"
     9		"fmt"
    10		"log"
    11		"os"
    12		"strings"
    13		"time"
    14	
    15		"github.com/scottdensmore/petspotr/pkg/blob"
    16		"github.com/scottdensmore/petspotr/pkg/delivery"
    17		"github.com/scottdensmore/petspotr/pkg/domain"
    18		"github.com/scottdensmore/petspotr/pkg/ollama"
    19		"github.com/scottdensmore/petspotr/pkg/outbox"
    20		"github.com/scottdensmore/petspotr/pkg/pubsub"
    21		"github.com/scottdensmore/petspotr/pkg/scoring"
    22		"github.com/scottdensmore/petspotr/pkg/store"
    23	)
    24	
    25	const (
    26		matcherDeliveryChannel = "matchFound"
    27		defaultMatcherLease    = 10 * time.Minute
    28	)
    29	
    30	// Store provides the durable state and delivery operations required by Worker.
    31	type Store interface {
    32		store.StateStore
    33		store.DeliveryOperationStore
    34		store.LostPetCandidateStore
    35	}
    36	
    37	type matcherResultRecord struct {
    38		InputEventID string `json:"inputEventId"`
    39		OutboxID     string `json:"outboxId"`
    40		MatchID      string `json:"matchId,omitempty"`
    41	}
    42	
    43	// Worker consumes foundPet events, extracts visual traits via Ollama, and matches against stored lost pets.
    44	type Worker struct {
    45		store        Store
    46		broker       pubsub.Publisher
    47		ollamaClient *ollama.Client
    48		modelName    string
    49		relay        *outbox.Relay
    50		now          func() time.Time
    51		lease        time.Duration
    52		images       blob.ImageStore
    53	}
    54	
    55	// NewWorker constructs a Worker instance.
    56	func NewWorker(st Store, br pubsub.Publisher, oc *ollama.Client) *Worker {
    57		return NewWorkerWithImageStore(st, br, oc, nil)
    58	}
    59	
    60	// NewWorkerWithImageStore constructs a worker that can read private finalized images.
    61	func NewWorkerWithImageStore(st Store, br pubsub.Publisher, oc *ollama.Client, images blob.ImageStore) *Worker {
    62		model := os.Getenv("OLLAMA_MODEL")
    63		if model == "" {
    64			model = "gemma4:e2b"
    65		}
    66		return &Worker{
    67			store:        st,
    68			broker:       br,
    69			ollamaClient: oc,
    70			modelName:    model,
    71			relay:        outbox.NewRelay(st, br),
    72			now:          time.Now,
    73			lease:        defaultMatcherLease,
    74			images:       images,
    75		}
    76	}
    77	
    78	// Start registers the foundPet topic subscription.
    79	func (w *Worker) Start(ctx context.Context) error {
    80		if err := ctx.Err(); err != nil {
    81			return err
    82		}
    83		broker, ok := w.broker.(pubsub.Broker)
    84		if !ok {
    85			return fmt.Errorf("pet-matcher: publisher does not support in-process subscriptions")
    86		}
    87		return broker.Subscribe("foundPet", func(handlerCtx context.Context, data []byte) error {
    88			return w.ProcessFoundPet(handlerCtx, data)
    89		})
    90	}
    91	
    92	// ProcessFoundPet processes a foundPet event payload.
    93	func (w *Worker) ProcessFoundPet(ctx context.Context, foundPetData []byte) error {
    94		if err := ctx.Err(); err != nil {
    95			return err
    96		}
    97		foundEvt, inputEnvelope, err := domain.DecodeFoundPetReported(foundPetData)
    98		if err != nil {
    99			return fmt.Errorf("pet-matcher: decode found-pet report: %w", err)
   100		}
   101		envelopeID := ""
   102		if inputEnvelope != nil {
   103			envelopeID = inputEnvelope.ID
   104		}
   105		inputEventID, err := delivery.ResolveEventID(envelopeID, domain.EventTypeFoundPetReported, foundPetData)
   106		if err != nil {
   107			return fmt.Errorf("pet-matcher: resolve foundPet identity: %w", err)
   108		}
   109		now := w.now().UTC()
   110		operation, err := delivery.NewOperation(inputEventID, foundEvt.PetID, matcherDeliveryChannel, now)
   111		if err != nil {
   112			return fmt.Errorf("pet-matcher: create processing operation: %w", err)
   113		}
   114		claim, err := w.store.ClaimDeliveryOperation(ctx, operation, now, w.lease)
   115		if err != nil {
   116			return fmt.Errorf("pet-matcher: claim foundPet processing: %w", err)
   117		}
   118		switch claim.State {
   119		case delivery.ClaimCompleted:
   120			return nil
   121		case delivery.ClaimInProgress:
   122			return fmt.Errorf("pet-matcher: foundPet processing: %w", delivery.ErrOperationInProgress)
   123		case delivery.ClaimAcquired:
   124		default:
   125			return fmt.Errorf("pet-matcher: unexpected processing claim %q", claim.State)
   126		}
   127	
   128		processErr := w.processClaimedFoundPet(ctx, inputEventID, inputEnvelope, foundEvt)
   129		if processErr == nil {
   130			processErr = w.store.CompleteDeliveryOperation(ctx, operation.ID, claim.Attempt, w.now().UTC())
   131		}
   132		if processErr == nil {
   133			return nil
   134		}
   135		failErr := w.store.FailDeliveryOperation(
   136			ctx,
   137			operation.ID,
   138			claim.Attempt,
   139			w.now().UTC(),
   140			processErr.Error(),
   141		)
   142		return errors.Join(processErr, failErr)
   143	}
   144	
   145	func (w *Worker) processClaimedFoundPet(
   146		ctx context.Context,
   147		inputEventID string,
   148		inputEnvelope *domain.EventEnvelope,
   149		foundEvt domain.FoundPetReportedV2,
   150	) error {
   151		if result, exists, err := w.loadMatcherResult(ctx, inputEventID); err != nil {
   152			return err
   153		} else if exists {
   154			return w.publishMatcherResult(ctx, result)
   155		}
   156		candidates, err := w.eligibleLostPetCandidates(ctx, foundEvt)
   157		if err != nil {
   158			return err
   159		}
   160		if len(candidates) == 0 {
   161			return nil
   162		}
   163	
   164		// 1. Analyze found pet image with Ollama + Gemma 4
   165		prompt := scoring.BuildGemmaPrompt("Pet", "")
   166		imageInput := foundEvt.ImageURL
   167		if foundEvt.ImageObject != "" {
   168			if w.images == nil {
   169				return errors.New("pet-matcher: private image store is not configured")
   170			}
   171			imageBytes, err := w.images.ReadFinalizedImage(ctx, foundEvt.ImageObject)
   172			if err != nil {
   173				return fmt.Errorf("pet-matcher: read private found-pet image: %w", err)
   174			}
   175			imageInput = base64.StdEncoding.EncodeToString(imageBytes)
   176		}
   177		genReq := &ollama.GenerateRequest{
   178			Model:  w.modelName,
   179			Prompt: prompt,
   180			Images: []string{imageInput},
   181		}
   182	
   183		genResp, err := w.ollamaClient.Generate(ctx, genReq)
   184		if err != nil {
   185			return fmt.Errorf("pet-matcher: Ollama generation failed: %w", err)
   186		}
   187	
   188		foundTraits, err := scoring.ParseGemmaResponse(genResp.Response)
   189		if err != nil {
   190			return fmt.Errorf("pet-matcher: failed to parse traits from Gemma response: %w", err)
   191		}
   192	
   193		// 2. Score every eligible candidate and choose a deterministic winner.
   194		var winner *rankedCandidate
   195		for index := range candidates {
   196			candidate := candidates[index]
   197			result := scoring.ComparePetsAtDistance(
   198				candidate.record.PetID,
   199				foundEvt.PetID,
   200				candidate.distanceMiles,
   201				candidate.traits,
   202				foundTraits,
   203			)
   204			if result == nil || !result.IsMatch {
   205				continue
   206			}
   207			challenger := rankedCandidate{candidate: candidate, result: result}
   208			if winner == nil || outranks(challenger, *winner) {
   209				winner = &challenger
   210			}
   211		}
   212		if winner != nil {
   213			matchResult := winner.result
   214			lostRecord := winner.candidate.record
   215			lostTraits := winner.candidate.traits
   216			lostPetID := lostRecord.PetID
   217			matchResult.SourceEventID = inputEventID
   218			matchResult.Model = genResp.Model
   219			if strings.TrimSpace(matchResult.Model) == "" {
   220				matchResult.Model = w.modelName
   221			}
   222			matchID, err := domain.StableMatchID(inputEventID, foundEvt.PetID, lostPetID)
   223			if err != nil {
   224				return fmt.Errorf("pet-matcher: derive match ID: %w", err)
   225			}
   226			matchResult.MatchID = matchID
   227			if matchResult.Scores == nil {
   228				return errors.New("pet-matcher: scoring result omitted score components")
   229			}
   230			matchedAt := w.now().UTC()
   231			lostBreed := lostRecord.Breed
   232			if lostBreed == "" {
   233				lostBreed = lostTraits.Breed
   234			}
   235			foundBreed := foundEvt.Breed
   236			if foundBreed == "" {
   237				foundBreed = foundTraits.Breed
   238			}
   239			matchRecord := domain.MatchRecord{
   240				MatchID:          matchID,
   241				FoundPetID:       foundEvt.PetID,
   242				MatchedPetID:     lostPetID,
   243				Score:            matchResult.Score,
   244				Status:           domain.MatchStatusPendingReview,
   245				MatchedAt:        matchedAt,
   246				Scores:           *matchResult.Scores,
   247				SourceEventID:    inputEventID,
   248				Model:            matchResult.Model,
   249				ThresholdVersion: matchResult.ThresholdVersion,
   250				Explanation:      matchResult.Details,
   251				LostPet: domain.MatchPetDetail{
   252					PetID:    lostPetID,
   253					PetName:  lostRecord.PetName,
   254					Breed:    lostBreed,
   255					Location: lostRecord.Location,
   256				},
   257				FoundPet: domain.MatchPetDetail{
   258					PetID:    foundEvt.PetID,
   259					Breed:    foundBreed,
   260					ImageURL: foundEvt.ImageURL,
   261					Location: foundEvt.Location,
   262				},
   263			}
   264			if err := matchRecord.Validate(); err != nil {
   265				return fmt.Errorf("pet-matcher: validate match record: %w", err)
   266			}
   267			resultBytes, err := matchResult.ToJSON()
   268			if err != nil {
   269				return fmt.Errorf("pet-matcher: failed to marshal MatchResult: %w", err)
   270			}
   271	
   272			correlationID := ""
   273			traceID := ""
   274			if inputEnvelope != nil {
   275				correlationID = inputEnvelope.CorrelationID
   276				traceID = inputEnvelope.TraceID
   277			}
   278			matchEnvelope, err := domain.NewEventEnvelope(domain.EventEnvelopeInput{
   279				Type:             domain.EventTypeMatchFound,
   280				OccurredAt:       matchedAt,
   281				CorrelationID:    correlationID,
   282				TraceID:          traceID,
   283				AggregateID:      matchResult.FoundPetID + ":" + matchResult.MatchedPetID,
   284				AggregateVersion: 1,
   285				PayloadVersion:   1,
   286				Payload:          resultBytes,
   287			})
   288			if err != nil {
   289				return fmt.Errorf("pet-matcher: failed to create matchFound envelope: %w", err)
   290			}
   291			envelopeBytes, err := json.Marshal(matchEnvelope)
   292			if err != nil {
   293				return fmt.Errorf("pet-matcher: failed to marshal matchFound envelope: %w", err)
   294			}
   295			resultRecord, err := w.persistMatcherResult(ctx, inputEventID, matchRecord, matchEnvelope.ID, envelopeBytes)
   296			if err != nil {
   297				return err
   298			}
   299			if err := w.publishMatcherResult(ctx, resultRecord); err != nil {
   300				return err
   301			}
   302	
   303			log.Printf("[Pet Matcher] MATCH FOUND! FoundPet: %s <-> LostPet: %s (Score: %.2f)",
   304				matchResult.FoundPetID, matchResult.MatchedPetID, matchResult.Score)
   305		}
   306	
   307		return nil
   308	}
   309	
   310	func (w *Worker) persistMatcherResult(
   311		ctx context.Context,
   312		inputEventID string,
   313		match domain.MatchRecord,
   314		outboxID string,
   315		payload []byte,
   316	) (matcherResultRecord, error) {
   317		record := matcherResultRecord{InputEventID: inputEventID, OutboxID: outboxID, MatchID: match.MatchID}
   318		stateData, err := json.Marshal(record)
   319		if err != nil {
   320			return matcherResultRecord{}, fmt.Errorf("pet-matcher: marshal matcher result: %w", err)
   321		}
   322		outboxRecord := outbox.NewRecord(outboxID, matcherDeliveryChannel, payload, w.now().UTC())
   323		outboxData, err := outbox.MarshalRecord(outboxRecord)
   324		if err != nil {
   325			return matcherResultRecord{}, fmt.Errorf("pet-matcher: marshal matchFound outbox: %w", err)
   326		}
   327		matchData, err := json.Marshal(match)
   328		if err != nil {
   329			return matcherResultRecord{}, fmt.Errorf("pet-matcher: marshal match record: %w", err)
   330		}
   331		_, err = w.store.CreateStatesAndOutbox(
   332			ctx,
   333			[]store.StateWrite{
   334				{StoreName: store.MatcherResultsCollection, Key: inputEventID, Data: stateData},
   335				{StoreName: store.MatchesCollection, Key: match.MatchID, Data: matchData},
   336			},
   337			store.StateWrite{StoreName: store.OutboxCollection, Key: outboxID, Data: outboxData},
   338		)
   339		if err == nil {
   340			return record, nil
   341		}
   342		if !errors.Is(err, store.ErrConflict) {
   343			return matcherResultRecord{}, fmt.Errorf("pet-matcher: persist matchFound result and outbox: %w", err)
   344		}
   345		winner, exists, loadErr := w.loadMatcherResult(ctx, inputEventID)
   346		if loadErr != nil {
   347			return matcherResultRecord{}, loadErr
   348		}
   349		if !exists {
   350			return matcherResultRecord{}, fmt.Errorf("pet-matcher: conflicting result has no durable winner: %w", err)
   351		}
   352		return winner, nil
   353	}
   354	
   355	func (w *Worker) loadMatcherResult(ctx context.Context, inputEventID string) (matcherResultRecord, bool, error) {
   356		data, err := w.store.GetState(ctx, store.MatcherResultsCollection, inputEventID)
   357		if errors.Is(err, store.ErrNotFound) || errors.Is(err, store.ErrStoreNotFound) {
   358			return matcherResultRecord{}, false, nil
   359		}
   360		if err != nil {
   361			return matcherResultRecord{}, false, fmt.Errorf("pet-matcher: load durable matcher result: %w", err)
   362		}
   363		var record matcherResultRecord
   364		if err := json.Unmarshal(data, &record); err != nil {
   365			return matcherResultRecord{}, false, fmt.Errorf("pet-matcher: decode durable matcher result: %w", err)
   366		}
   367		if record.InputEventID != inputEventID || record.OutboxID == "" {
   368			return matcherResultRecord{}, false, errors.New("pet-matcher: durable matcher result identity is invalid")
   369		}
   370		return record, true, nil
   371	}
   372	
   373	func (w *Worker) publishMatcherResult(ctx context.Context, result matcherResultRecord) error {
   374		if _, err := w.relay.PublishRecords(ctx, result.OutboxID); err != nil {
   375			return fmt.Errorf("pet-matcher: publish durable matchFound result: %w", err)
   376		}
   377		record, err := outbox.GetRecord(ctx, w.store, result.OutboxID)
   378		if err != nil {
   379			return fmt.Errorf("pet-matcher: load matchFound outbox result: %w", err)
   380		}
