    18	// Client is an HTTP client for interacting with an Ollama instance.
    19	type Client struct {
    20		baseURL    string
    21		httpClient *http.Client
    22	}
    23	
    24	// Option configures a Client instance.
    25	type Option func(*Client)
    26	
    27	// WithBaseURL overrides the default Ollama base URL.
    28	func WithBaseURL(url string) Option {
    29		return func(c *Client) {
    30			if strings.TrimSpace(url) != "" {
    31				c.baseURL = strings.TrimSuffix(url, "/")
    32			}
    33		}
    34	}
    35	
    36	// WithHTTPClient overrides the default http.Client.
    37	func WithHTTPClient(hc *http.Client) Option {
    38		return func(c *Client) {
    39			if hc != nil {
    40				c.httpClient = hc
    41			}
    42		}
    43	}
    44	
    45	// NewClient constructs a new Ollama client.
    46	func NewClient(opts ...Option) *Client {
    47		baseURL := os.Getenv("OLLAMA_HOST")
    48		if baseURL == "" {
    49			baseURL = defaultBaseURL
    50		}
    51	
    52		c := &Client{
    53			baseURL: strings.TrimSuffix(baseURL, "/"),
    54			httpClient: &http.Client{
    55				Timeout: 60 * time.Second,
    56			},
    57		}
    58	
    59		for _, opt := range opts {
    60			if opt != nil {
    61				opt(c)
    62			}
    63		}
    64		return c
    65	}
