   137	
   138	func (c *Client) doRequest(ctx context.Context, path string, reqBody interface{}, respBody interface{}) error {
   139		if err := ctx.Err(); err != nil {
   140			return err
   141		}
   142	
   143		data, err := json.Marshal(reqBody)
   144		if err != nil {
   145			return fmt.Errorf("ollama: failed to marshal request: %w", err)
   146		}
   147	
   148		url := fmt.Sprintf("%s%s", c.baseURL, path)
   149		httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, url, bytes.NewReader(data))
   150		if err != nil {
   151			return fmt.Errorf("ollama: failed to create request: %w", err)
   152		}
   153		httpReq.Header.Set("Content-Type", "application/json")
   154	
   155		httpResp, err := c.httpClient.Do(httpReq)
   156		if err != nil {
   157			return fmt.Errorf("ollama: request failed: %w", err)
   158		}
   159		defer func() { _ = httpResp.Body.Close() }()
   160	
   161		if httpResp.StatusCode < 200 || httpResp.StatusCode >= 300 {
   162			bodyBytes, _ := io.ReadAll(httpResp.Body)
   163			var errResp struct {
   164				Error string `json:"error"`
   165			}
   166			if err := json.Unmarshal(bodyBytes, &errResp); err == nil && strings.TrimSpace(errResp.Error) != "" {
   167				return fmt.Errorf("ollama: API returned status code %d: %s", httpResp.StatusCode, errResp.Error)
   168			}
   169			return fmt.Errorf("ollama: API returned status code %d", httpResp.StatusCode)
   170		}
   171	
   172		if err := json.NewDecoder(httpResp.Body).Decode(respBody); err != nil {
   173			return fmt.Errorf("ollama: failed to decode response: %w", err)
   174		}
   175	
   176		return nil
   177	}
     1	package scoring
     2	
     3	import (
     4		"fmt"
     5		"math"
     6		"strings"
     7	
     8		"github.com/scottdensmore/petspotr/pkg/domain"
     9	)
    10	
    11	const (
    12		WeightBreed           = 0.40
    13		WeightPrimaryColor    = 0.20
    14		WeightSecondaryColor  = 0.10
    15		WeightMarkings        = 0.20
    16		WeightEyeColor        = 0.10
    17		MatchThreshold        = 0.70
    18		MatchRadiusMiles      = 15.0
    19		MatchThresholdVersion = "visual-spatial-v1"
    20	)
    21	
    22	// CalculateMatchScore computes a weighted similarity score between 0.0 and 1.0.
    23	func CalculateMatchScore(t1, t2 *PetTraits) float64 {
    24		if t1 == nil || t2 == nil {
    25			return 0.0
    26		}
    27	
    28		var score float64
    29	
    30		// 1. Breed match (0.40)
    31		if compareStrings(t1.Breed, t2.Breed) {
    32			score += WeightBreed
    33		}
    34	
    35		// 2. Primary color match (0.20)
    36		if compareStrings(t1.PrimaryColor, t2.PrimaryColor) {
    37			score += WeightPrimaryColor
    38		}
    39	
    40		// 3. Secondary color match (0.10)
    41		if compareStrings(t1.SecondaryColor, t2.SecondaryColor) {
    42			score += WeightSecondaryColor
    43		}
    44	
    45		// 4. Distinctive markings match (0.20)
    46		score += WeightMarkings * compareMarkings(t1.DistinctiveMarkings, t2.DistinctiveMarkings)
    47	
    48		// 5. Eye color match (0.10)
    49		if compareStrings(t1.EyeColor, t2.EyeColor) {
    50			score += WeightEyeColor
    51		}
    52	
    53		return math.Min(1.0, math.Max(0.0, score))
    54	}
    55	
    56	// CalculateDistanceScore computes a spatial score between 0.0 and 1.0 based on physical distance miles.
    57	func CalculateDistanceScore(distanceMiles, maxRadiusMiles float64) float64 {
    58		if maxRadiusMiles <= 0 {
    59			maxRadiusMiles = 15.0
    60		}
    61		if distanceMiles <= 0 {
    62			return 1.0
    63		}
    64		if distanceMiles >= maxRadiusMiles {
    65			return 0.0
    66		}
    67		return math.Max(0.0, 1.0-(distanceMiles/maxRadiusMiles))
    68	}
    69	
    70	// CalculateCombinedMatchScore combines visual similarity (70% weight) and spatial proximity (30% weight).
    71	func CalculateCombinedMatchScore(visualScore, spatialScore float64) float64 {
    72		combined := (0.70 * visualScore) + (0.30 * spatialScore)
    73		return math.Min(1.0, math.Max(0.0, combined))
    74	}
    75	
    76	// ComparePets generates a validated domain.MatchResult from two pet trait sets.
    77	func ComparePets(lostPetID, foundPetID string, lostTraits, foundTraits *PetTraits) *domain.MatchResult {
    78		return ComparePetsGeo(lostPetID, foundPetID, "", "", lostTraits, foundTraits)
    79	}
    80	
    81	// ComparePetsGeo generates a validated domain.MatchResult combining visual similarity and spatial distance.
    82	func ComparePetsGeo(lostPetID, foundPetID, lostLocation, foundLocation string, lostTraits, foundTraits *PetTraits) *domain.MatchResult {
    83		p1 := domain.ParseLocationCoordinates(lostLocation)
    84		p2 := domain.ParseLocationCoordinates(foundLocation)
    85		distMiles := domain.HaversineDistanceMiles(p1, p2)
    86		return ComparePetsAtDistance(lostPetID, foundPetID, distMiles, lostTraits, foundTraits)
    87	}
    88	
    89	// ComparePetsAtDistance generates a validated MatchResult from an explicit,
    90	// verified distance without parsing or inventing location coordinates.
    91	func ComparePetsAtDistance(lostPetID, foundPetID string, distMiles float64, lostTraits, foundTraits *PetTraits) *domain.MatchResult {
    92		if math.IsNaN(distMiles) || math.IsInf(distMiles, 0) || distMiles < 0 {
    93			return nil
    94		}
    95		visualScore := CalculateMatchScore(lostTraits, foundTraits)
    96		spatialScore := CalculateDistanceScore(distMiles, MatchRadiusMiles)
    97		colorScore := calculateColorScore(lostTraits, foundTraits)
    98	
    99		combinedScore := CalculateCombinedMatchScore(visualScore, spatialScore)
   100		isMatch := combinedScore >= MatchThreshold
   101	
   102		details := fmt.Sprintf("Match score: %.2f (Visual: %.2f, Spatial: %.2f, Distance: %.1f mi, Threshold: %.2f)",
   103			combinedScore, visualScore, spatialScore, distMiles, MatchThreshold)
   104	
   105		res := &domain.MatchResult{
   106			FoundPetID:   foundPetID,
   107			MatchedPetID: lostPetID,
   108			Score:        combinedScore,
   109			IsMatch:      isMatch,
   110			Details:      details,
   111			Scores: &domain.MatchScoreBreakdown{
   112				Visual:        visualScore,
   113				Color:         colorScore,
   114				Spatial:       spatialScore,
   115				DistanceMiles: distMiles,
   116				Threshold:     MatchThreshold,
   117			},
   118			ThresholdVersion: MatchThresholdVersion,
   119		}
   120	
   121		if err := res.Validate(); err != nil {
   122			return nil
   123		}
   124	
   125		return res
   126	}
   127	
   128	func calculateColorScore(first, second *PetTraits) float64 {
   129		if first == nil || second == nil {
   130			return 0
   131		}
   132		compared := 0
   133		matched := 0
   134		for _, colors := range [][2]string{
   135			{first.PrimaryColor, second.PrimaryColor},
   136			{first.SecondaryColor, second.SecondaryColor},
   137		} {
   138			if strings.TrimSpace(colors[0]) == "" || strings.TrimSpace(colors[1]) == "" {
   139				continue
   140			}
   141			compared++
   142			if compareStrings(colors[0], colors[1]) {
   143				matched++
   144			}
   145		}
   146		if compared == 0 {
   147			return 0
   148		}
   149		return float64(matched) / float64(compared)
   150	}
   151	
   152	func compareStrings(s1, s2 string) bool {
   153		s1Clean := strings.TrimSpace(strings.ToLower(s1))
   154		s2Clean := strings.TrimSpace(strings.ToLower(s2))
   155		if s1Clean == "" || s2Clean == "" {
   156			return false
   157		}
   158		return s1Clean == s2Clean
   159	}
   160	
   161	func compareMarkings(m1, m2 []string) float64 {
   162		set1 := make(map[string]bool)
   163		for _, item := range m1 {
   164			clean := strings.TrimSpace(strings.ToLower(item))
   165			if clean != "" {
   166				set1[clean] = true
   167			}
   168		}
   169	
   170		set2 := make(map[string]bool)
   171		for _, item := range m2 {
   172			clean := strings.TrimSpace(strings.ToLower(item))
   173			if clean != "" {
   174				set2[clean] = true
   175			}
   176		}
   177	
   178		if len(set1) == 0 && len(set2) == 0 {
   179			return 1.0
   180		}
   181	
   182		matches := 0
   183		for k := range set2 {
   184			if set1[k] {
   185				matches++
   186			}
   187		}
   188	
   189		union := len(set1)
   190		for k := range set2 {
   191			if !set1[k] {
   192				union++
   193			}
   194		}
   195	
   196		if union == 0 {
   197			return 0.0
   198		}
   199	
   200		return float64(matches) / float64(union)
   201	}
     1	package petmatcher
     2	
     3	import (
     4		"context"
     5		"encoding/json"
     6		"fmt"
     7		"log"
     8		"math"
     9		"sort"
    10		"strings"
    11		"time"
    12	
    13		"github.com/scottdensmore/petspotr/pkg/domain"
    14		"github.com/scottdensmore/petspotr/pkg/scoring"
    15		"github.com/scottdensmore/petspotr/pkg/store"
    16	)
    17	
    18	const (
    19		matcherCandidateWindow      = 30 * 24 * time.Hour
    20		matcherCandidateRadiusMiles = scoring.MatchRadiusMiles
    21	)
    22	
    23	type lostPetCandidate struct {
    24		record        domain.LostPetRecord
    25		distanceMiles float64
    26		traits        *scoring.PetTraits
    27	}
    28	
    29	type rankedCandidate struct {
    30		candidate lostPetCandidate
    31		result    *domain.MatchResult
    32	}
    33	
    34	func outranks(challenger, current rankedCandidate) bool {
    35		if challenger.result.Score != current.result.Score {
    36			return challenger.result.Score > current.result.Score
    37		}
    38		if challenger.candidate.distanceMiles != current.candidate.distanceMiles {
    39			return challenger.candidate.distanceMiles < current.candidate.distanceMiles
    40		}
    41		return challenger.candidate.record.PetID < current.candidate.record.PetID
    42	}
    43	
    44	func (w *Worker) eligibleLostPetCandidates(
    45		ctx context.Context,
    46		found domain.FoundPetReportedV2,
    47	) ([]lostPetCandidate, error) {
    48		if found.GeocodingStatus != domain.GeocodingVerified || found.Coordinates == nil {
    49			return nil, nil
    50		}
    51		if err := found.Coordinates.Validate(); err != nil {
    52			return nil, fmt.Errorf("pet-matcher: validate found-pet coordinates: %w", err)
    53		}
    54		rawCandidates := make(map[string][]byte)
    55		for _, query := range boundedCandidateQueries(found) {
    56			queryResults, err := w.store.QueryLostPetCandidates(ctx, query)
    57			if err != nil {
    58				return nil, fmt.Errorf("pet-matcher: query lost-pet candidates: %w", err)
    59			}
    60			for key, data := range queryResults {
    61				rawCandidates[key] = data
    62			}
    63		}
    64	
    65		candidates := make([]lostPetCandidate, 0, len(rawCandidates))
    66		for key, data := range rawCandidates {
    67			var record domain.LostPetRecord
    68			if err := json.Unmarshal(data, &record); err != nil {
    69				log.Printf("[Pet Matcher] Skipping malformed lost-pet candidate %q", key)
    70				continue
    71			}
    72			record = domain.NormalizeLostPetRecord(record)
    73			if record.PetID == "" || record.PetID != key {
    74				log.Printf("[Pet Matcher] Skipping lost-pet candidate %q with mismatched identity", key)
    75				continue
    76			}
    77			if record.Status != domain.LostPetStatusLost || record.GeocodingStatus != domain.GeocodingVerified ||
    78				record.Coordinates == nil || record.ReportedAt.IsZero() {
    79				continue
    80			}
    81			if err := record.Coordinates.Validate(); err != nil {
    82				log.Printf("[Pet Matcher] Skipping lost-pet candidate %q with invalid coordinates", key)
    83				continue
    84			}
    85			age := found.FoundAt.Sub(record.ReportedAt)
    86			if age < 0 {
    87				age = -age
    88			}
    89			if age > matcherCandidateWindow {
    90				continue
    91			}
    92			if found.Species != "" && record.Species != "" && !strings.EqualFold(found.Species, record.Species) {
    93				continue
    94			}
    95			distanceMiles := domain.HaversineDistanceMiles(*found.Coordinates, *record.Coordinates)
    96			if distanceMiles > matcherCandidateRadiusMiles {
    97				continue
    98			}
    99			traits := &scoring.PetTraits{
   100				Breed:        record.Breed,
   101				PrimaryColor: record.PrimaryColor,
   102			}
   103			if description := strings.TrimSpace(record.Description); description != "" {
   104				traits.DistinctiveMarkings = []string{description}
   105			}
   106			candidates = append(candidates, lostPetCandidate{
   107				record: record, distanceMiles: distanceMiles, traits: traits,
   108			})
   109		}
   110		sort.Slice(candidates, func(i, j int) bool {
   111			return candidates[i].record.PetID < candidates[j].record.PetID
   112		})
   113		return candidates, nil
   114	}
   115	
   116	func boundedCandidateQueries(found domain.FoundPetReportedV2) []store.LostPetCandidateQuery {
   117		latitudeDelta := matcherCandidateRadiusMiles / 69.0
   118		longitudeMilesPerDegree := 69.0 * math.Cos(found.Coordinates.Latitude*math.Pi/180)
