     8	func resolveRuntimeMode(lookup func(string) string) (Mode, bool, error) {
     9		rawMode := strings.TrimSpace(lookup("PETSPOTR_RUNTIME_MODE"))
    10		cloudRun := strings.TrimSpace(lookup("K_SERVICE")) != ""
    11		if rawMode == "" {
    12			if cloudRun {
    13				rawMode = string(ModeGCP)
    14			} else {
    15				rawMode = string(ModeMemory)
    16			}
    17		}
    18	
    19		mode := Mode(rawMode)
    20		switch mode {
    21		case ModeMemory, ModeLocalEmulator, ModeGCP:
    22		default:
    23			return mode, cloudRun, fmt.Errorf("unsupported PETSPOTR_RUNTIME_MODE %q", rawMode)
    24		}
    25		if cloudRun && mode != ModeGCP {
    26			return mode, true, fmt.Errorf("runtime mode %q is not allowed on Cloud Run", mode)
    27		}
    28		return mode, cloudRun, nil
    29	}
