		data, err := s.store.GetState(checkCtx, store.LostPetsCollection, reportID)
		if errors.Is(err, store.ErrNotFound) || errors.Is(err, store.ErrStoreNotFound) {
			return false, nil
		}
		if err != nil {
		reportOperationTimeout: options.ReportOperationTimeout,
	}
}

